import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';


export type SensorComparisonProps = Record<string, any>;

const SensorComparison: React.FC<SensorComparisonProps> = ({
  backgroundColor = "#0F172A",
  transparentBackground = false,
  durationInSeconds = 10,
  ffColor = "#F59E0B",
  apscColor = "#3B82F6",
  textColor = "#F8FAFC",
  titleText = "Sensor Size Comparison",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser-safe background color
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  const helveticaFont = "Helvetica, Arial, sans-serif";

  // Sensor dimensions at accurate relative scale (18x factor)
  // Full Frame: ~36 x 24 mm -> 648 x 432 px
  const ffW = 648;
  const ffH = 432;
  // APS-C (Sony/Nikon ~1.5x crop): ~23.6 x 15.6 mm -> 425 x 281 px
  const apscW = 425;
  const apscH = 281;

  // Layout targets
  const centerY = height * 0.5 + 40;
  const centerX = width / 2;
  const ffTargetX = 610; // Left offset
  const apscTargetX = 1310; // Right offset

  // Animations
  const titleOpacity = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp" });
  const titleY = spring({ frame, fps, config: { damping: 14 } });

  const ffSpawn = spring({ frame: frame - 15, fps, config: { damping: 12, stiffness: 90 } });
  const apscSpawn = spring({ frame: frame - 40, fps, config: { damping: 12, stiffness: 90 } });

  const separateProgress = spring({
    frame: frame - 80,
    fps,
    config: { damping: 16, stiffness: 60, mass: 1.2 },
  });

  const ffX = interpolate(separateProgress, [0, 1], [centerX, ffTargetX]);
  const apscX = interpolate(separateProgress, [0, 1], [centerX, apscTargetX]);

  const overlayTextOpacity = interpolate(separateProgress, [0, 0.3], [1, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const separatedElementsOpacity = interpolate(separateProgress, [0.7, 1], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: helveticaFont, fontWeight: "bold" }}>
      {/* Title */}
      <div
        style={{
          position: "absolute",
          top: 80,
          left: 0,
          width: "100%",
          textAlign: "center",
          opacity: titleOpacity,
          transform: `translateY(${interpolate(titleY, [0, 1], [-30, 0])}px)`,
          transition: "none",
        }}
      >
        <h1
          style={{
            margin: 0,
            fontSize: 56,
            fontWeight: "bold",
            color: textColor,
            letterSpacing: "-0.02em",
          }}
        >
          {titleText}
        </h1>
        <p
          style={{
            margin: "12px 0 0 0",
            fontSize: 24,
            fontWeight: "bold",
            color: `${textColor}99`,
          }}
        >
          Visualising the 1.5x Crop Factor
        </p>
      </div>

      {/* Full Frame Sensor */}
      <div
        style={{
          position: "absolute",
          left: ffX,
          top: centerY,
          width: ffW,
          height: ffH,
          backgroundColor: ffColor,
          borderRadius: 8,
          transform: `translate(-50%, -50%) scale(${ffSpawn})`,
          boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.4)",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
          zIndex: 1,
        }}
      >
        {/* Inner active area simulation */}
        <div
          style={{
            width: "92%",
            height: "88%",
            backgroundColor: "rgba(0,0,0,0.15)",
            borderRadius: 4,
            border: "1px solid rgba(255,255,255,0.2)",
          }}
        />
      </div>

      {/* Ghost Outline of Full Frame over APS-C */}
      <div
        style={{
          position: "absolute",
          left: apscX,
          top: centerY,
          width: ffW,
          height: ffH,
          border: `3px dashed ${textColor}66`,
          borderRadius: 8,
          transform: `translate(-50%, -50%)`,
          opacity: separatedElementsOpacity,
          zIndex: 2,
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* APS-C Sensor */}
      <div
        style={{
          position: "absolute",
          left: apscX,
          top: centerY,
          width: apscW,
          height: apscH,
          backgroundColor: apscColor,
          borderRadius: 6,
          transform: `translate(-50%, -50%) scale(${apscSpawn})`,
          boxShadow: "0 10px 30px -5px rgba(0, 0, 0, 0.5)",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
          zIndex: 3,
        }}
      >
        {/* Inner active area simulation */}
        <div
          style={{
            width: "90%",
            height: "85%",
            backgroundColor: "rgba(0,0,0,0.15)",
            borderRadius: 4,
            border: "1px solid rgba(255,255,255,0.2)",
          }}
        />
      </div>

      {/* Stacked Label (Visible only when overlaid) */}
      <div
        style={{
          position: "absolute",
          top: centerY + ffH / 2 + 50,
          left: centerX,
          transform: "translate(-50%, 0)",
          opacity: Math.min(
            interpolate(frame, [50, 60], [0, 1], { extrapolateRight: "clamp" }),
            overlayTextOpacity
          ),
          textAlign: "center",
          transition: "none",
        }}
      >
        <div style={{ color: textColor, fontSize: 24, fontWeight: "bold" }}>
          Sensors Overlaid
        </div>
      </div>

      {/* Separated Labels (Aligned along the same horizontal line) */}
      <div
        style={{
          position: "absolute",
          top: centerY + ffH / 2 + 60,
          left: ffX,
          transform: "translate(-50%, 0)",
          opacity: separatedElementsOpacity,
          textAlign: "center",
          transition: "none",
        }}
      >
        <div style={{ color: ffColor, fontSize: 36, fontWeight: "bold", marginBottom: 8 }}>
          Full Frame
        </div>
        <div style={{ color: `${textColor}cc`, fontSize: 24, fontWeight: "bold" }}>
          36 × 24 mm
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          top: centerY + ffH / 2 + 60,
          left: apscX,
          transform: "translate(-50%, 0)",
          opacity: separatedElementsOpacity,
          textAlign: "center",
          transition: "none",
        }}
      >
        <div style={{ color: apscColor, fontSize: 36, fontWeight: "bold", marginBottom: 8 }}>
          APS-C
        </div>
        <div style={{ color: `${textColor}cc`, fontSize: 24, fontWeight: "bold" }}>
          23.6 × 15.6 mm
        </div>
        <div
          style={{
            marginTop: 16,
            display: "inline-block",
            padding: "6px 16px",
            backgroundColor: `${apscColor}22`,
            border: `1px solid ${apscColor}55`,
            borderRadius: 20,
            color: apscColor,
            fontSize: 18,
            fontWeight: "bold",
          }}
        >
          1.5x Crop
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SensorComparison;